mapper.update:
UPDATE invoice
   SET billing_status = 'PAID',
       paid_at        = #{paidAt},
       projected_at   = #{projectedAt},
       last_event_id  = #{lastEventId}
 WHERE invoice_id = #{invoiceId}

UPDATE invoice
   SET billing_status = 'VOID',
       void_marker    = #{invoiceId},
       projected_at   = #{projectedAt},
       last_event_id  = #{lastEventId}
 WHERE invoice_id = #{invoiceId}

UPDATE invoice
   SET billing_status = 'INVOICED',
       paid_at        = NULL,
       projected_at   = #{projectedAt},
       last_event_id  = #{lastEventId}
 WHERE invoice_id = #{invoiceId}

UPDATE payment
   SET voided_at   = #{voidedAt},
       voided_by   = #{voidedBy},
       void_reason = #{reason}
 WHERE payment_id = #{paymentId}
